// Beide sheets expliciet bij naam ophalen, zodat de node-volgorde niet uitmaakt.
function haalOp(naam) {
  try { return $(naam).all().map(i => i.json); } catch (e) { return []; }
}

let facturen = haalOp('Haal facturen op');
let fouten   = haalOp('Haal fouten op');

if (facturen.length === 0) {
  const directeInput = $input.all().map(i => i.json);
  if (directeInput.some(r => r && r.validatieResultaat !== undefined)) {
    facturen = directeInput;
  }
}

// ── Helpers ──────────────────────────────────────────────────────────────────
function num(v) {
  if (v == null || v === '') return 0;
  if (typeof v === 'number') return v;
  let s = String(v).trim();
  if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) s = s.replace(',', '.');
  const n = parseFloat(s.replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}
function bool(v) {
  if (v === true) return true;
  if (v == null) return false;
  return ['true', 'waar', 'ja', '1', 'yes'].includes(String(v).trim().toLowerCase());
}
function pct(deel, geheel) { return geheel > 0 ? Math.round((deel / geheel) * 100) : 0; }

function datumDeel(v) {
  if (!v) return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})/);
  if (m) return m[3] + '-' + String(m[2]).padStart(2, '0') + '-' + String(m[1]).padStart(2, '0');
  const d = new Date(s);
  if (!isNaN(d.getTime())) return d.toISOString().slice(0, 10);
  return null;
}

// ── Weekvenster ────────────────────────────────────────────────────────────
const nowNL = new Date().toLocaleString('sv', { timeZone: 'Europe/Amsterdam' });
const vandaagStr = nowNL.slice(0, 10);
const basis = new Date(vandaagStr + 'T12:00:00Z');
const weekdag = basis.getUTCDay();
const dagenSindsMaandag = (weekdag + 6) % 7;
function isoMin(date, dagen) { const d = new Date(date); d.setUTCDate(d.getUTCDate() - dagen); return d.toISOString().slice(0, 10); }
const startStr = isoMin(basis, dagenSindsMaandag + 7);
const eindStr  = isoMin(basis, dagenSindsMaandag + 1);
function nlDatum(s) { const p = s.split('-'); return p[2] + '-' + p[1] + '-' + p[0]; }
const periodeLabel = nlDatum(startStr) + ' t/m ' + nlDatum(eindStr);

function inWeek(v) { const d = datumDeel(v); return d !== null && d >= startStr && d <= eindStr; }
facturen = facturen.filter(f => inWeek(f.verwerktOp));
fouten   = fouten.filter(fo => inWeek(fo.verwerktOp) || inWeek(fo.foutdatum) || inWeek(fo.datum));

// ── Aggregatie ────────────────────────────────────────────────────────────
const totaal = facturen.length;
let pass = 0, review = 0, fatal = 0;
let totaalBedrag = 0, totaalBtw = 0, totaalBetaalbaar = 0, totaalRegels = 0;
const leveranciers = new Set();

let ibanAfwijkingen = 0, nieuweLeveranciers = 0, lageBetrouwbaarheid = 0;
let techPass = 0, techReview = 0, techFatal = 0, techFoutenTotaal = 0;
let omgerekendTotaal = 0, geflagdTotaal = 0, nvtTotaal = 0;
let docConfSom = 0, docConfN = 0;
let pctGlSom = 0, pctGlN = 0;
let levConfSom = 0, levConfN = 0, uniekGematcht = 0;
const matchMethode = { btw: 0, kvk: 0, iban: 0, naam: 0, geen: 0, overig: 0 };
const perLeverancier = {};

const aandachtMap = {};
const redenRang = { 'Geblokkeerd (FATAL)': 0, 'IBAN-afwijking': 1, 'Technische fout': 2, 'Nieuwe leverancier': 3, 'Lage betrouwbaarheid': 4 };

for (const f of facturen) {
  const res = String(f.validatieResultaat || '').toUpperCase();
  if (res === 'PASS') pass++;
  else if (res === 'REVIEW') review++;
  else if (res === 'FATAL') fatal++;

  totaalBedrag     += num(f.totaalbedrag);
  totaalBtw        += num(f.btwbedrag);
  totaalBetaalbaar += num(f.betaalbaarBedrag);
  totaalRegels     += num(f.aantalRegels);

  const lev = f.leveranciernaam || 'Onbekend';
  leveranciers.add(lev);

  if (!perLeverancier[lev]) perLeverancier[lev] = { totaal: 0, confSom: 0, confN: 0 };
  perLeverancier[lev].totaal++;

  const heeftIbanAfw = bool(f.ibanAfwijking);
  const isNieuw      = bool(f.nieuweOnbekendeLeverancier);
  const lageBtr      = bool(f.betrouwbaarheidIsLaag);
  if (heeftIbanAfw) ibanAfwijkingen++;
  if (isNieuw)      nieuweLeveranciers++;
  if (lageBtr)      lageBetrouwbaarheid++;

  const tech = String(f.technischResultaat || '').toUpperCase();
  if (tech === 'PASS') techPass++;
  else if (tech === 'REVIEW') techReview++;
  else if (tech === 'FATAL') techFatal++;
  techFoutenTotaal += num(f.aantalTechnischeFouten);

  omgerekendTotaal += num(f.aantalOmgerekend);
  geflagdTotaal    += num(f.aantalGeflagd);
  nvtTotaal        += num(f.aantalNietVanToepassing);

  if (f.documentConfidence != null && f.documentConfidence !== '') { docConfSom += num(f.documentConfidence); docConfN++; }
  if (f.percentageRegelsZonderGl != null && f.percentageRegelsZonderGl !== '') { pctGlSom += num(f.percentageRegelsZonderGl); pctGlN++; }

  if (f.leverancierConfidence != null && f.leverancierConfidence !== '') {
    const lc = num(f.leverancierConfidence);
    levConfSom += lc; levConfN++;
    perLeverancier[lev].confSom += lc; perLeverancier[lev].confN++;
  }
  if (bool(f.leverancierUniekGematcht)) uniekGematcht++;
  const mmK = String(f.leverancierMatchMethode || '').toLowerCase();
  if (matchMethode[mmK] !== undefined) matchMethode[mmK]++;
  else if (mmK) matchMethode.overig++;
  else matchMethode.geen++;

  const redenen = [];
  if (res === 'FATAL')      redenen.push('Geblokkeerd (FATAL)');
  if (heeftIbanAfw)         redenen.push('IBAN-afwijking');
  if (tech === 'FATAL')     redenen.push('Technische fout');
  if (isNieuw)              redenen.push('Nieuwe leverancier');
  if (lageBtr)              redenen.push('Lage betrouwbaarheid');

  if (redenen.length) {
    const fnr = f.factuurnummer || '';
    const mapKey = fnr + '||' + lev;
    const zwaarste = redenen.sort((a, b) => (redenRang[a] ?? 99) - (redenRang[b] ?? 99))[0];
    const huidigBedrag = num(f.totaalbedrag);
    if (!aandachtMap[mapKey]) {
      aandachtMap[mapKey] = { factuurnummer: fnr || '-', leveranciernaam: lev, bedrag: huidigBedrag, reden: zwaarste, rang: redenRang[zwaarste] ?? 99 };
    } else {
      if ((redenRang[zwaarste] ?? 99) < aandachtMap[mapKey].rang) {
        aandachtMap[mapKey].reden = zwaarste;
        aandachtMap[mapKey].rang  = redenRang[zwaarste] ?? 99;
      }
      if (huidigBedrag > aandachtMap[mapKey].bedrag) {
        aandachtMap[mapKey].bedrag = huidigBedrag;
      }
    }
  }
}

// ── KPI 1: FIX #3 — bij lege week stpPct op null zetten ──────────────────
const handmatigPct = pct(review + fatal, totaal);
const stpPct = totaal > 0 ? (100 - handmatigPct) : null;
const doelAutomatisch = 60;
const doelGehaald = stpPct !== null && stpPct >= doelAutomatisch;
const oranjedrempel = Math.round(doelAutomatisch * 2 / 3);

// ── KPI 4 ──────────────────────────────────────────────────────────────────
const techTotaal = techPass + techReview + techFatal;
const techPassPct = pct(techPass, techTotaal);

// ── Gemiddelden ────────────────────────────────────────────────────────────
const gemDocConfPct  = docConfN > 0 ? Math.round((docConfSom / docConfN) * 100) : 0;
const gemLevConfPct  = levConfN > 0 ? Math.round((levConfSom / levConfN) * 100) : 0;
const gemPctZonderGl = pctGlN  > 0 ? Math.round(pctGlSom / pctGlN) : 0;
const uniekPct       = pct(uniekGematcht, totaal);

// ── KPI 2 ──────────────────────────────────────────────────────────────────
const aantalLeveranciers = leveranciers.size;
const heatmapMax = 8;
const heatmapGesorteerd = Object.entries(perLeverancier).map(([naam, d]) => ({
  naam,
  conf: d.confN > 0 ? Math.round((d.confSom / d.confN) * 100) : null
})).sort((a, b) => {
  if (a.conf === null && b.conf === null) return 0;
  if (a.conf === null) return 1;
  if (b.conf === null) return -1;
  return a.conf - b.conf;
});
const heatmap = heatmapGesorteerd.slice(0, heatmapMax);
const verborgenLevs = heatmapGesorteerd.slice(heatmapMax);
const heatmapVerborgen = verborgenLevs.length;
const verborgenAllesGoed = verborgenLevs.length > 0 && verborgenLevs.every(l => l.conf !== null && l.conf >= 90);
const heatmapVoetnootTekst = heatmapVerborgen > 0
  ? (verborgenAllesGoed
      ? `Toont ${heatmap.length} van ${aantalLeveranciers} leveranciers \u00b7 overige leveranciers hebben voldoende matchkwaliteit.`
      : `Toont ${heatmap.length} van ${aantalLeveranciers} leveranciers \u00b7 overige leveranciers niet weergegeven.`)
  : '';

// ── KPI 3: FIX #1 — zwaarste severity per foutcode bijhouden ─────────────
const sevRang = { 'FATAL': 0, 'REVIEW': 1, 'ONBEKEND': 2 };
const foutTeller = {};
let foutenFatal = 0, foutenReview = 0, foutenOverig = 0;
for (const fo of fouten) {
  const code = fo.foutcode || 'onbekend';
  const sev  = String(fo.severity || '').toUpperCase() || 'ONBEKEND';
  if (sev === 'FATAL') foutenFatal++;
  else if (sev === 'REVIEW') foutenReview++;
  else foutenOverig++;
  if (!foutTeller[code]) {
    foutTeller[code] = { code, aantal: 0, voorbeeld: fo.omschrijving || '', severity: sev, sevRang: sevRang[sev] ?? 99 };
  } else {
    // FIX #1: zwaarste severity bijwerken als deze ernstiger is
    const nieuwRang = sevRang[sev] ?? 99;
    if (nieuwRang < foutTeller[code].sevRang) {
      foutTeller[code].severity = sev;
      foutTeller[code].sevRang  = nieuwRang;
    }
  }
  foutTeller[code].aantal++;
}
const topFouten = Object.values(foutTeller).sort((a, b) => b.aantal - a.aantal).slice(0, 5);

// ── Aandacht: FIX #2 — totaalteller voor afkap-melding ───────────────────
const alleAandacht = Object.values(aandachtMap).sort((a, b) => b.bedrag - a.bedrag);
const aandacht = alleAandacht.slice(0, 10);
const aandachtVerborgen = alleAandacht.length - aandacht.length;

return [{ json: {
  periodeLabel, periodeStart: startStr, periodeEind: eindStr,
  aantalFacturen: totaal, aantalRegels: totaalRegels,
  aantalPass: pass, aantalReview: review, aantalFatal: fatal,
  totaalBedrag, totaalBtw, totaalBetaalbaar, aantalLeveranciers,
  handmatigPct, stpPct, doelAutomatisch, doelGehaald, oranjedrempel,
  ibanAfwijkingen, nieuweLeveranciers, lageBetrouwbaarheid,
  techPass, techReview, techFatal, techPassPct, techTotaal, techFoutenTotaal,
  omgerekendTotaal, geflagdTotaal, nvtTotaal, gemDocConfPct, gemPctZonderGl,
  gemLevConfPct, uniekPct, uniekGematcht, matchMethode,
  heatmap, heatmapVerborgen, heatmapVoetnootTekst,
  topFouten, foutenFatal, foutenReview, foutenOverig,
  aandacht, aandachtVerborgen
} }];

const s = $input.first().json;
const eur = n => '\u20ac ' + Number(n || 0).toLocaleString('nl-NL', {minimumFractionDigits: 2, maximumFractionDigits: 2});
const mv = (n, enk, meerv) => n + ' ' + (Number(n) === 1 ? enk : meerv);
const legeWeek = s.aantalFacturen === 0;

function kpi(label, waarde, kleur) {
  return `<td width="25%" style="padding:6px">
    <table width="100%" cellpadding="0" cellspacing="0" style="background:#f7fafc;border-radius:8px">
      <tr><td style="padding:12px;text-align:center">
        <div style="font-size:10px;color:#718096;text-transform:uppercase;letter-spacing:0.5px">${label}</div>
        <div style="font-size:20px;font-weight:700;color:${kleur||'#1a202c'};margin-top:4px">${waarde}</div>
      </td></tr></table></td>`;
}

function riskCard(label, waarde, sub) {
  const alarm = Number(waarde) > 0;
  const bg = alarm ? '#fcebeb' : '#e1f5ee';
  const fg = alarm ? '#a32d2d' : '#0f6e56';
  return `<td width="25%" style="padding:6px">
    <table width="100%" cellpadding="0" cellspacing="0" style="background:${bg};border-radius:8px">
      <tr><td style="padding:12px;text-align:center">
        <div style="font-size:10px;color:${fg};text-transform:uppercase;letter-spacing:0.5px">${label}</div>
        <div style="font-size:22px;font-weight:700;color:${fg};margin-top:4px">${waarde}</div>
        <div style="font-size:10px;color:${fg};margin-top:2px">${sub||''}</div>
      </td></tr></table></td>`;
}

function balk(pctWaarde, kleur, label) {
  const p = Math.max(0, Math.min(100, Number(pctWaarde)||0));
  const binnenBreedte = p > 0 ? `width:${p}%` : 'display:none';
  return `<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:6px">
    <tr><td style="background:#e2e8f0;border-radius:99px;height:24px">
      <table cellpadding="0" cellspacing="0" style="${binnenBreedte};min-width:${p > 0 ? '40px' : '0'}"><tr>
        <td style="background:${kleur};border-radius:99px;height:24px;text-align:center;color:white;font-weight:700;font-size:12px">${p > 0 ? p + '%' : ''}</td>
      </tr></table>
    </td></tr></table>
    ${label ? `<div style="font-size:12px;color:#718096;margin-top:6px">${label}</div>` : ''}`;
}

function confKleur(c) {
  if (c === null) return 'background:#edf2f7;color:#718096';
  if (c >= 90) return 'background:#e1f5ee;color:#0f6e56';
  if (c >= 75) return 'background:#faeeda;color:#854f0b';
  return 'background:#fcebeb;color:#a32d2d';
}
function sevKleur(x) {
  if (x === 'FATAL')    return 'background:#fcebeb;color:#a32d2d';
  if (x === 'REVIEW')   return 'background:#faeeda;color:#854f0b';
  return 'background:#edf2f7;color:#4a5568';
}
function redenKleur(r) {
  if (r === 'Geblokkeerd (FATAL)') return 'background:#fcebeb;color:#a32d2d';
  if (r === 'IBAN-afwijking')      return 'background:#fcebeb;color:#a32d2d';
  if (r === 'Technische fout')     return 'background:#fcebeb;color:#a32d2d';
  if (r === 'Nieuwe leverancier')  return 'background:#faeeda;color:#854f0b';
  return 'background:#fef3c7;color:#854f0b';
}

// FIX #4: leegBanner + conditoneel alle KPI-secties overslaan bij lege week
const leegBanner = legeWeek
  ? `<tr><td style="padding:24px 28px;text-align:center">
      <div style="background:#eef2f7;border-radius:8px;padding:20px">
        <div style="font-size:16px;font-weight:600;color:#4a5568;margin-bottom:4px">Geen facturen verwerkt</div>
        <div style="font-size:13px;color:#718096">In de week van ${s.periodeLabel} zijn er geen facturen verwerkt.</div>
      </div>
    </td></tr>`
  : '';

// FIX #3: KPI 1 balk alleen tonen als er facturen zijn (stpPct !== null)
const balkKleur = s.doelGehaald ? '#0f6e56' : (s.stpPct >= s.oranjedrempel ? '#854f0b' : '#a32d2d');
const gaugeBalk = s.stpPct !== null
  ? balk(s.stpPct, balkKleur, `${s.stpPct}% automatisch \u00b7 doel min. ${s.doelAutomatisch}% automatisch \u00b7 ${s.doelGehaald ? 'doel gehaald' : 'doel nog niet gehaald'}`)
  : `<div style="font-size:12px;color:#a0aec0;margin-top:6px;font-style:italic">Geen data beschikbaar voor deze periode.</div>`;

const techReviewLabel = s.techReview > 0 ? ` \u00b7 ${s.techReview} technisch review` : '';
const techBalk = balk(
  s.techPassPct,
  s.techPassPct >= 95 ? '#0f6e56' : (s.techPassPct >= 80 ? '#854f0b' : '#a32d2d'),
  `${s.techPass} van ${s.techTotaal} facturen technisch valide${techReviewLabel} \u00b7 ${s.techFoutenTotaal} technische fouten totaal`
);

const heatRijen = s.heatmap.length
  ? s.heatmap.map(h => `<tr>
  <td style="padding:7px;border-bottom:1px solid #edf2f7;font-size:13px">${h.naam}</td>
  <td style="padding:7px;border-bottom:1px solid #edf2f7;text-align:center">
    <span style="${confKleur(h.conf)};padding:2px 10px;border-radius:6px;font-size:12px;font-weight:600">${h.conf !== null ? h.conf + '%' : '-'}</span>
  </td>
</tr>`).join('')
  : '<tr><td colspan="2" style="padding:10px;text-align:center;color:#a0aec0;font-size:13px">Geen facturen in deze periode</td></tr>';

const heatmapVoetnoot = s.heatmapVoetnootTekst
  ? `<div style="font-size:11px;color:#a0aec0;margin-top:6px;text-align:right">${s.heatmapVoetnootTekst}</div>`
  : '';

const foutenOverigLabel = s.foutenOverig > 0 ? ` \u00b7 ${mv(s.foutenOverig, 'onbekend type', 'onbekende types')}` : '';
const foutRijen = s.topFouten.length
  ? s.topFouten.map(f => `<tr>
      <td style="padding:5px 7px;border-bottom:1px solid #edf2f7;font-family:monospace;font-size:12px;white-space:nowrap">${f.code}</td>
      <td style="padding:5px 7px;border-bottom:1px solid #edf2f7;text-align:center"><span style="${sevKleur(f.severity)};padding:1px 7px;border-radius:6px;font-size:11px;font-weight:600">${f.severity}</span></td>
      <td style="padding:5px 7px;border-bottom:1px solid #edf2f7;font-size:12px">${f.voorbeeld}</td>
      <td style="padding:5px 7px;border-bottom:1px solid #edf2f7;text-align:center;font-weight:600;font-size:12px">${f.aantal}</td>
    </tr>`).join('')
  : '<tr><td colspan="4" style="padding:10px;text-align:center;color:#0f6e56;font-size:13px">Geen fouten deze week</td></tr>';

// FIX #2: voetnoot bij afkap aandachtsfacturen
const aandachtVoetnoot = s.aandachtVerborgen > 0
  ? `<div style="font-size:11px;color:#a0aec0;margin-top:6px;text-align:right">Toont 10 van ${s.aandacht.length + s.aandachtVerborgen} facturen \u00b7 overige ${s.aandachtVerborgen} niet weergegeven.</div>`
  : '';

const aandachtRijen = s.aandacht.length
  ? s.aandacht.map(a => `<tr>
      <td style="padding:6px 7px;border-bottom:1px solid #edf2f7;font-family:monospace;font-size:12px">${a.factuurnummer}</td>
      <td style="padding:6px 7px;border-bottom:1px solid #edf2f7;font-size:12px">${a.leveranciernaam}</td>
      <td style="padding:6px 7px;border-bottom:1px solid #edf2f7;text-align:right;font-size:12px">${eur(a.bedrag)}</td>
      <td style="padding:6px 7px;border-bottom:1px solid #edf2f7"><span style="${redenKleur(a.reden)};padding:1px 8px;border-radius:6px;font-size:11px;font-weight:600;white-space:nowrap">${a.reden}</span></td>
    </tr>`).join('')
  : '<tr><td colspan="4" style="padding:10px;text-align:center;color:#0f6e56;font-size:13px">Geen facturen met risicosignalen deze week</td></tr>';

const mm = s.matchMethode || {};
const matchSamenvatting = `BTW ${mm.btw||0} \u00b7 KvK ${mm.kvk||0} \u00b7 IBAN ${mm.iban||0} \u00b7 Naam ${mm.naam||0} \u00b7 Geen ${mm.geen||0}`;

// FIX #4: bij lege week alleen header + banner + footer, geen KPI-blokken
const kpiSectie = legeWeek ? '' : `
  <tr><td style="padding:16px 22px 4px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Facturen', s.aantalFacturen, '#1a202c')}
      ${kpi('Factuurregels', s.aantalRegels, '#1a202c')}
      ${kpi('Leveranciers', s.aantalLeveranciers, '#1a202c')}
      ${kpi('Totaal incl. BTW', eur(s.totaalBedrag), '#1a202c')}
    </tr></table>
  </td></tr>

  <tr><td style="padding:4px 22px 8px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Goedgekeurd', s.aantalPass, '#0f6e56')}
      ${kpi('Review', s.aantalReview, '#854f0b')}
      ${kpi('Actie nodig', s.aantalFatal, '#a32d2d')}
      ${kpi('BTW-bedrag', eur(s.totaalBtw), '#1a202c')}
    </tr></table>
  </td></tr>

  <tr><td style="padding:10px 28px 4px">
    <div style="font-size:15px;font-weight:600;color:#1a202c;margin-bottom:6px">Risicosignalen \u00b7 betaal- en fraudecontrole</div>
  </td></tr>
  <tr><td style="padding:0 22px 8px">
    <table width="100%" cellpadding="0" cellspacing="0"><tr>
      ${riskCard('IBAN-afwijking', s.ibanAfwijkingen, 'verifieer rekening')}
      ${riskCard('Nieuwe leverancier', s.nieuweLeveranciers, 'niet in stamdata')}
      ${riskCard('Lage betrouwbaarheid', s.lageBetrouwbaarheid, 'AI-confidence laag')}
      ${riskCard('Technische fouten', s.techFatal, 'UBL-validatie')}
    </tr></table>
  </td></tr>

  <tr><td style="padding:12px 28px 4px">
    <div style="font-size:15px;font-weight:600;color:#1a202c;margin-bottom:6px">KPI 1 \u00b7 Reductie handmatige handelingen</div>
